import {ancestorPaths} from './kinship.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export class FamilyCharts{
 constructor(svg,onSelect){this.svg=svg;this.onSelect=onSelect;this.positions=new Map();this.box={x:0,y:0,w:960,h:600};this.drag=null;
 svg.addEventListener('pointerdown',e=>{const node=e.target.closest('[data-person]');this.drag={id:node?.dataset.person,x:e.clientX,y:e.clientY,box:{...this.box},moved:false};svg.setPointerCapture(e.pointerId);});
 svg.addEventListener('pointermove',e=>{if(!this.drag)return;const dx=e.clientX-this.drag.x,dy=e.clientY-this.drag.y;if(Math.hypot(dx,dy)>4)this.drag.moved=true;if(!this.drag.moved)return;const scale=1/svg.getScreenCTM().a;if(this.drag.id){const point=new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse());this.positions.set(this.drag.id,{x:point.x,y:point.y});this.paint();}else{this.box.x=this.drag.box.x-dx*scale;this.box.y=this.drag.box.y-dy*scale;this.viewport();}});
 svg.addEventListener('pointerup',()=>{const d=this.drag;this.drag=null;if(d?.id&&!d.moved)this.onSelect(d.id);});svg.addEventListener('pointercancel',()=>this.drag=null);
 svg.addEventListener('keydown',e=>{const id=e.target.closest('[data-person]')?.dataset.person;if(id&&(e.key==='Enter'||e.key===' ')){e.preventDefault();this.onSelect(id);}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-','0'].includes(e.key)){e.preventDefault();if(e.key==='0')this.box={x:0,y:0,w:960,h:600};else if(e.key==='+'||e.key==='-')this.zoom(e.key==='+'?.85:1.15);else{this.box.x+=e.key==='ArrowLeft'?-30:e.key==='ArrowRight'?30:0;this.box.y+=e.key==='ArrowUp'?-30:e.key==='ArrowDown'?30:0;}this.viewport();}});
 svg.addEventListener('wheel',e=>{if(e.ctrlKey)return;e.preventDefault();this.zoom(Math.exp(Math.max(-100,Math.min(100,e.deltaY))*.002));},{passive:false});
 }
 viewport(){this.svg.setAttribute('viewBox',`${this.box.x} ${this.box.y} ${this.box.w} ${this.box.h}`);}
 zoom(f){const w=Math.max(300,Math.min(2400,this.box.w*f)),h=w*600/960;this.box.x+=(this.box.w-w)/2;this.box.y+=(this.box.h-h)/2;this.box.w=w;this.box.h=h;this.viewport();}
 render(people,edges,mode,selected,path=[]){this.selected=selected;this.path=path;this.mode=mode;
 const ancestors=ancestorPaths(selected,edges);this.people=mode==='ancestors'?people.filter(p=>ancestors.has(p.id)):people;const ids=new Set(this.people.map(p=>p.id));this.edges=edges.filter(([a,b,t])=>ids.has(a)&&ids.has(b)&&(mode!=='ancestors'||t==='parent'));
 const key=mode+'|'+this.people.map(p=>p.id).join(',')+(mode==='ancestors'?'|'+selected:'');
 if(this.key!==key){this.key=key;this.positions=new Map();this.box={x:0,y:0,w:960,h:600};
 if(mode==='ancestors'){const rows=new Map();for(const p of this.people){const d=ancestors.get(p.id).length-1;if(!rows.has(d))rows.set(d,[]);rows.get(d).push(p);}const depth=Math.max(...rows.keys(),1);for(const[d,row]of rows)row.forEach((p,i)=>this.positions.set(p.id,{x:(i+1)*960/(row.length+1),y:530-d*460/depth}));}
 else{this.people.forEach((p,i)=>this.positions.set(p.id,{x:480+250*Math.cos(i*2*Math.PI/this.people.length),y:300+210*Math.sin(i*2*Math.PI/this.people.length)}));for(let k=0;k<250;k++){const forces=new Map(this.people.map(p=>[p.id,{x:0,y:0}]));for(let i=0;i<this.people.length;i++)for(let j=i+1;j<this.people.length;j++){const a=this.positions.get(this.people[i].id),b=this.positions.get(this.people[j].id),dx=a.x-b.x,dy=a.y-b.y,d=Math.max(1,Math.hypot(dx,dy)),f=6500/(d*d);forces.get(this.people[i].id).x+=dx/d*f;forces.get(this.people[i].id).y+=dy/d*f;forces.get(this.people[j].id).x-=dx/d*f;forces.get(this.people[j].id).y-=dy/d*f;}for(const[a,b]of this.edges){const p=this.positions.get(a),q=this.positions.get(b),dx=q.x-p.x,dy=q.y-p.y,d=Math.max(1,Math.hypot(dx,dy)),f=(d-135)*.018;forces.get(a).x+=dx/d*f;forces.get(a).y+=dy/d*f;forces.get(b).x-=dx/d*f;forces.get(b).y-=dy/d*f;}for(const[id,p]of this.positions){const f=forces.get(id);p.x=Math.max(85,Math.min(875,p.x+f.x+(480-p.x)*.001));p.y=Math.max(50,Math.min(510,p.y+f.y+(300-p.y)*.001));}}}
 }
 this.svg.innerHTML=this.edges.map(([a,b,t])=>`<line data-a="${a}" data-b="${b}" class="chart-edge ${t}"/>`).join('')+this.people.map(p=>`<g data-person="${p.id}" role="button" tabindex="0" aria-label="${esc(p.name)}" class="chart-node"><circle r="${p.id===selected?19:12}"/><text y="35" text-anchor="middle">${esc(p.name)}</text></g>`).join('');this.viewport();this.paint();
 }
 paint(){this.svg.querySelectorAll('[data-person]').forEach(n=>{const p=this.positions.get(n.dataset.person);n.setAttribute('transform',`translate(${p.x},${p.y})`);n.classList.toggle('chosen',n.dataset.person===this.selected);n.classList.toggle('on-path',this.path.includes(n.dataset.person));});this.svg.querySelectorAll('line').forEach(l=>{const a=this.positions.get(l.dataset.a),b=this.positions.get(l.dataset.b);for(const[k,v]of Object.entries({x1:a.x,y1:a.y,x2:b.x,y2:b.y}))l.setAttribute(k,v);l.classList.toggle('on-path',this.path.some((id,i)=>i&&((id===l.dataset.a&&this.path[i-1]===l.dataset.b)||(id===l.dataset.b&&this.path[i-1]===l.dataset.a))));});}
}
